inline HMODULE hIl2Cpp = NULL;

struct Il2CppClass
{
	static Il2CppClass* FromTypeDefinitionIndex(DWORD Index)
	{
		return ((Il2CppClass * (*)(DWORD))((PBYTE)hIl2Cpp + IL2CPPCLASS_FROMTYPEDEFINITIONINDEX_OFFSET))(Index);
	}

	LPCSTR GetName()
	{
		return ((LPCSTR(*)(PVOID))((PBYTE)hIl2Cpp + IL2CPPCLASS_GETNAME_OFFSET))(this);
	}

	LPCSTR GetNamespace()
	{
		return ((LPCSTR(*)(PVOID))((PBYTE)hIl2Cpp + IL2CPPCLASS_GETNAMESPACE_OFFSET))(this);
	}

	Il2CppClass* GetParent()
	{
		return ((Il2CppClass * (*)(PVOID))((PBYTE)hIl2Cpp + IL2CPPCLASS_GETPARENT_OFFSET))(this);
	}

	PVOID GetStaticField()
	{
		return ((PVOID(*)(PVOID))((PBYTE)hIl2Cpp + IL2CPPCLASS_GETSTATICFIELD_OFFSET))(this);
	}
};

struct Il2CppObject
{
	union
	{
		Il2CppClass* klass;
		PVOID vtable;
	};

	PVOID monitor;
};

struct Il2CppArrayBounds
{
	SIZE_T length;
	SIZE_T lower_bound;
};

template <typename T>
struct Il2CppArray
{
	Il2CppObject obj;
	Il2CppArrayBounds* bounds;
	SIZE_T max_length;
	T vector[32];
};

namespace System
{
	using Void = void; using Boolean = bool; using Char = wchar_t; using SByte = int8_t;
	using Byte = uint8_t; using Int16 = int16_t; using UInt16 = uint16_t; using Int32 = int32_t;
	using UInt32 = uint32_t; using Int64 = int64_t; using UInt64 = uint64_t; using Single = float;
	using Double = double; using IntPtr = intptr_t; using UIntPtr = uintptr_t;
	class Object; class String; class Type; class Array; class Enum; class ValueType;
	class Delegate; class MulticastDelegate; class Attribute; class Exception;
}

static void UnitySDK_Initialize(HMODULE module) { hIl2Cpp = module; }

